package Picture;

public class MakePicture {

    /**
     *
     * @param width Width in integer
     * @param height Height in integer
     * @return Array of bytes with the header for the bmp file
     */
    public static byte[] makeHeader(int width, int height) {
        // HEADER
        // THE HARDCODED BYTES WERE GENERATED BY CHATGPT CLANKER IM LAZY
        //
        // TO CHANGE RESOLUTION SEARCH FOR COMMENTED BYTES
        // THE BYTES CHANGED NEED TO BE IN LITTLE ENDIAN

        // CONVERSION FROM INT TO LITTLE ENDIAN BYTE FROM GEEKSSHARED.NET
        //
        // TAKES AN INTEGER AND SPLITS IT INTO 4 BLOCKS OF 1 BYTE EACH -> 4 BYTES

        // EXAMPLE
        // WIDTH = 1280 = 0x00000500
        // HEIGHT = 720 = 0x000002D0

        byte[] widthB = new byte[4];
        widthB[0] = (byte) (width & 0xff);
        widthB[1] = (byte) (width >> 8 & 0xff);
        widthB[2] = (byte) (width >> 16 & 0xff);
        widthB[3] = (byte) (width >> 24 & 0xff);

        byte[] heightB = new byte[4];
        heightB[0] = (byte) (height & 0xff);
        heightB[1] = (byte) (height >> 8 & 0xff);
        heightB[2] = (byte) (height >> 16 & 0xff);
        heightB[3] = (byte) (height >> 24 & 0xff);

        return new byte[]{
                // FILE HEADER
                (byte) 0x42, // B
                (byte) 0x4D, // M

                (byte) 0x36,
                (byte) 0x30,
                (byte) 0x2A,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x36,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x28,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,

                widthB[0], // X
                widthB[1],
                widthB[2],
                widthB[3],

                heightB[0], // Y
                heightB[1],
                heightB[2],
                heightB[3],

                (byte) 0x01,
                (byte) 0x00,
                (byte) 0x18,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x30,
                (byte) 0x2A,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00
        };
    }
}
